#nullable enable // autogenerated

using MukioI18n;
using MVZ2.GameContent.Contraptions;
using MVZ2.GameContent.Pickups;
using MVZ2.Vanilla.Definitions;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Localization;
using MVZ2.Vanilla.Pickups;
using MVZ2.Vanilla.RandomChina;
using MVZ2Logic.Blueprints;
using PVZEngine.Entities;
using PVZEngine.Tools.Random;

namespace MVZ2.GameContent.RandomChinaEvents
{
    [RandomChinaEventDefinition(VanillaRandomChinaEventNames.justice)]
    public class JusticeEvent : RandomChinaEventDefinition
    {
        public JusticeEvent(string nsp, string path) : base(nsp, path, NAME, DESCRIPTION)
        {
        }
        public override void Run(Entity contraption, RandomGenerator rng)
        {
            var level = contraption.Level;
            contraption.Produce(VanillaPickupID.redstone);
            contraption.Produce(VanillaPickupID.ruby);
            contraption.ProduceStarshard(contraption.GetCenter());
            var param = contraption.GetSpawnParams();
            param.SetProperty(VanillaPickupProps.CONTENT_ID, LogicBlueprintID.FromEntity(VanillaContraptionID.tnt));
            contraption.Produce(VanillaPickupID.blueprintPickup, param);
        }
        [TranslateMsg("随机瓷器事件名称", VanillaStrings.CONTEXT_RANDOM_CHINA_EVENT_NAME)]
        public const string NAME = "XI-正义";
        [TranslateMsg("随机瓷器事件描述", VanillaStrings.CONTEXT_RANDOM_CHINA_EVENT_DESCRIPTION)]
        public const string DESCRIPTION = "生成红石、红宝石、星之碎片和TNT蓝图各一个";
    }
}
